float motor_current_amps(float v_supply, float r_ohm, float ke_v_per_rads, float omega_rads) {
  float v_emf = ke_v_per_rads * omega_rads;
  return (v_supply - v_emf) / r_ohm;
}

void decode_hbridge_command(int signed_cmd, int* in1_out, int* in2_out, int* pwm_out) {
  if (signed_cmd > 0) {
    *in1_out = HIGH;
    *in2_out = LOW;
    *pwm_out = signed_cmd;
  } else if (signed_cmd < 0) {
    *in1_out = LOW;
    *in2_out = HIGH;
    *pwm_out = -signed_cmd;
  } else {
    *in1_out = LOW;
    *in2_out = LOW;
    *pwm_out = 0;
  }
}

